@@ -0,0 +1,35 @@
+// Sites: the kitchens Larder serves. Every location belongs to one site, and
+// a batch belongs to the site of its location. Batches, stock on hand,
+// cooking, alerts, stock value and stock-takes only see one site; items,
+// suppliers, recipes and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in list order. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site a location belongs to (locations missing from the list predate sites, so `main`). */
+export function locationSite(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site ?? DEFAULT_SITE;
+}
+
+/** True when the location exists and belongs to `site` (any site when `site` is null or undefined). */
+export function isSiteLocation(store, site, locationId) {
+  return store.data.locations.some((l) => l.id === locationId && (site === null || site === undefined || l.site === site));
+}
+
+/** True when `site` is null or undefined (every site) or the record's (batch, stock-take) location belongs to it. */
+export function inSite(store, site, record) {
+  return site === null || site === undefined || locationSite(store, record.location) === site;
+}
